// ================= Manga Card =================
const MangaCard = ({ manga }: { manga: MangaItem }) => (
  <Link
    to={`/detail/?title=${encodeURIComponent(manga.title)}`}
    className="group flex flex-col w-full min-w-[120px] max-w-[180px] mx-auto"
  >
    <div className="relative w-full overflow-hidden rounded-r-xl">
      {manga.rating && (
        <span className="absolute z-10 top-1 right-1 text-[10px] px-2 py-0.5 rounded-full bg-[#C667F7]">
          {manga.rating}
        </span>
      )}

      <img
        src={manga.thumbnail}
        alt={manga.title}
        className="w-full aspect-[2/3] object-cover bg-gray-700 transition-transform duration-300 group-hover:scale-105"
      />

      <span className="absolute bottom-0 left-0 w-full text-xs p-2 bg-gradient-to-t from-black/80 to-transparent">
        AniList
      </span>
    </div>

    <span className="text-xs font-semibold text-center py-2 px-1 line-clamp-2">
      {manga.title}
    </span>
  </Link>
)

// ================= Advance Search Modal =================
const AdvanceSearchModal = ({
  open,
  onClose,
  onApply,
}: {
  open: boolean
  onClose: () => void
  onApply: (v: { title: string; genre: string; adult: boolean }) => void
}) => {
  const [title, setTitle] = useState("")
  const [genre, setGenre] = useState("")
  const [adult, setAdult] = useState(false)

  if (!open) return null

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      <div
        className="absolute inset-0 bg-black/50 backdrop-blur-sm"
        onClick={onClose}
      />

      <div className="relative z-10 w-full max-w-md rounded-2xl bg-[#1e1e1e] p-6 animate-scaleIn">
        <button
          onClick={onClose}
          className="absolute top-4 right-4 text-gray-400 hover:text-white"
        >
          <FaXmark />
        </button>

        <h2 className="text-lg font-semibold mb-4 flex items-center gap-2">
          <FaFilter /> Advance Search
        </h2>

        <div className="space-y-3">
          <input
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="Judul manga…"
            className="w-full px-3 py-2 rounded-lg bg-[#2a2a2a] outline-none"
          />

          <input
            value={genre}
            onChange={(e) => setGenre(e.target.value)}
            placeholder="Genre (Romance, Action, dll)"
            className="w-full px-3 py-2 rounded-lg bg-[#2a2a2a] outline-none"
          />

          <label className="flex items-center gap-2 text-sm">
            <input
              type="checkbox"
              checked={adult}
              onChange={() => setAdult(!adult)}
            />
            Tampilkan Adult
          </label>
        </div>

        <button
          onClick={() => {
            onApply({ title, genre, adult })
            onClose()
          }}
          className="mt-5 w-full py-2 rounded-xl bg-[#C667F7] font-semibold hover:opacity-90"
        >
          Terapkan
        </button>
      </div>
    </div>
  )
}

// ================= Main Page =================
const MangaListPage = () => {
  const [modalOpen, setModalOpen] = useState(false)
  const [filter, setFilter] = useState({
    title: "",
    genre: "",
    adult: false,
  })

  const filteredData = useMemo(() => {
    return db.data.filter((m) => {
      if (filter.title && !m.title.toLowerCase().includes(filter.title.toLowerCase()))
        return false

      if (filter.genre && !m.genres.some((g) =>
        g.toLowerCase().includes(filter.genre.toLowerCase())
      )) return false

      if (!filter.adult && m.isAdult) return false

      return true
    })
  }, [filter])

  return (
    <>
      {/* Header */}
      <div className="max-w-screen-xl mx-auto px-3 mb-4 flex justify-between items-center">
        <h1 className="text-lg font-semibold">Manga Library</h1>

        <button
          onClick={() => setModalOpen(true)}
          className="flex items-center gap-2 text-sm px-3 py-2 rounded-xl bg-[#2a2a2a] hover:bg-[#3a3a3a]"
        >
          <FaMagnifyingGlass />
          Advance Search
        </button>
      </div>

      {/* Grid */}
      <div className="w-full grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-3 max-w-screen-xl mx-auto px-2">
        {filteredData.map((manga) => (
          <MangaCard key={manga.title} manga={manga} />
        ))}
      </div>

      <AdvanceSearchModal
        open={modalOpen}
        onClose={() => setModalOpen(false)}
        onApply={setFilter}
      />
    </>
  )
}

export default MangaListPage